<?php
/**
 * Newsletter — custom post type registration
 * ================================================================
 *
 * Registers:
 *   • `pixel_newsletter` CPT — one post per newsletter edition (drafts
 *     and sent). Minimal supports (title only) because everything else
 *     is generated by the cron and surfaced via metaboxes (see admin.php).
 *   • `newsletter_sent` custom post status — distinct from `publish` so
 *     we can tell at a glance which editions have been dispatched and
 *     so the cron knows not to re-send them.
 *
 * Constants used here are defined in the parent file
 * (inc/newsletter-issues.php).
 *
 * @package newpixel
 */

if ( ! defined( 'ABSPATH' ) ) { exit; }

add_action( 'init', 'newpixel_newsletter_register_cpt' );
function newpixel_newsletter_register_cpt() {
    register_post_type( NEWPIXEL_NEWSLETTER_CPT, array(
        'label'              => __( 'Newsletter', 'newpixel' ),
        'labels'             => array(
            'name'               => __( 'Newsletter Issues', 'newpixel' ),
            'singular_name'      => __( 'Issue', 'newpixel' ),
            'add_new'            => __( 'New Issue', 'newpixel' ),
            'add_new_item'       => __( 'New Issue', 'newpixel' ),
            'edit_item'          => __( 'Edit Issue', 'newpixel' ),
            'view_item'          => __( 'View Issue', 'newpixel' ),
            'search_items'       => __( 'Search Issues', 'newpixel' ),
            'menu_name'          => __( 'Newsletter', 'newpixel' ),
        ),
        'public'             => false,
        'show_ui'            => true,
        'show_in_menu'       => true,
        'show_in_admin_bar'  => false,
        'show_in_rest'       => false,
        'menu_icon'          => 'dashicons-email-alt',
        'menu_position'      => 26,
        'capability_type'    => 'post',
        'map_meta_cap'       => true,
        // Only 'title' so the edit screen is naturally minimal — the rest
        // of the content (article cards, footer, etc.) is generated by
        // the cron and not editable. The editor's one knob — the
        // headline — is added as a separate meta box.
        'supports'           => array( 'title' ),
        'has_archive'        => false,
        'rewrite'            => false,
    ) );

    // Custom status: 'newsletter_sent'. Distinct from 'publish' so we can
    // tell at a glance which issues have actually been dispatched, and so
    // the cron knows not to re-send the same issue.
    register_post_status( NEWPIXEL_NEWSLETTER_STATUS_SENT, array(
        'label'                     => _x( 'Sent', 'post status', 'newpixel' ),
        'public'                    => false,
        'internal'                  => false,
        'protected'                 => true,
        'show_in_admin_status_list' => true,
        'show_in_admin_all_list'    => true,
        /* translators: %s: number of issues with this status */
        'label_count'               => _n_noop( 'Sent <span class="count">(%s)</span>', 'Sent <span class="count">(%s)</span>', 'newpixel' ),
    ) );
}
